#include <WiFi.h>
#include <WebServer.h>

// आपके एयरटेल वाई-फाई का SSID और Password
const char* ssid = "Airtel_murs_9118";
const char* password = "air@10295";

// पोर्ट 80 पर वेब सर्वर शुरू करें
WebServer server(80);

// एलईडी पिन (ESP32-S3 बोर्ड के लिए)
const int ledPin = 38; 

void handleRoot() {
  String html = "<!DOCTYPE html><html><head>";
  html += "<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">";
  html += "<style>";
  html += "body { font-family: Arial; text-align: center; margin-top: 50px; background-color: #f4f4f9; }";
  html += "h1 { color: #333; }";
  html += ".btn { display: inline-block; padding: 15px 30px; font-size: 20px; cursor: pointer; text-align: center; text-decoration: none; outline: none; color: #fff; background-color: #4CAF50; border: none; border-radius: 15px; box-shadow: 0 9px #999; margin: 10px;}";
  html += ".btn:hover {background-color: #3e8e41}";
  html += ".btn:active { background-color: #3e8e41; box-shadow: 0 5px #666; transform: translateY(4px); }";
  html += ".off { background-color: #f44336; box-shadow: 0 9px #d32f2f; }";
  html += ".off:hover { background-color: #d32f2f; }";
  html += "</style></head><body>";
  html += "<h1>SADIK.AI ESP32-S3 Web Control</h1>";
  html += "<p>Control your robot board from OnePlus 15R</p>";
  html += "<a href=\"/ledon\"><button class=\"btn\">LED ON</button></a>";
  html += "<a href=\"/ledoff\"><button class=\"btn off\">LED OFF</button></a>";
  html += "</body></html>";

  server.send(200, "text/html", html);
}

void handleLedOn() {
  digitalWrite(ledPin, HIGH);
  server.sendHeader("Location", "/");
  server.send(303);
}

void handleLedOff() {
  digitalWrite(ledPin, LOW);
  server.sendHeader("Location", "/");
  server.send(303);
}

void setup() {
  Serial.begin(115200);
  pinMode(ledPin, OUTPUT);
  digitalWrite(ledPin, LOW);

  // वाई-फाई से कनेक्ट करें
  WiFi.begin(ssid, password);
  Serial.println("Connecting to WiFi");

  while (WiFi.status() != WL_CONNECTED) {
    delay(500);
    Serial.print(".");
  }

  Serial.println("");
  Serial.println("WiFi connected.");
  Serial.print("IP address: ");
  Serial.println(WiFi.localIP());

  // वेब पेज रूट्स सेट करें
  server.on("/", handleRoot);
  server.on("/ledon", handleLedOn);
  server.on("/ledoff", handleLedOff);

  server.begin();
  Serial.println("HTTP server started");
}

void loop() {
  server.handleClient();
}
